-- Generated by generate.py. Edit the palette there and regenerate.
local active_border_color = { colors = { "#26a6a6", "#bcd42a", "#ff5d38" }, angle = 45 }
local inactive_border_color = "#414858"

hl.config({
  general = {
    col = {
      active_border = active_border_color,
      inactive_border = inactive_border_color,
    },
  },
  group = {
    col = {
      border_active = active_border_color,
      border_inactive = inactive_border_color,
    },
  },
  decoration = {
    blur = {
      enabled = true,
      size = 8,
      passes = 3,
      brightness = 0.82,
      vibrancy = 0.17,
      new_optimizations = true,
    },
  },
})

-- Frost the translucent shell surfaces. ignore_alpha keeps the launcher's dimmed
-- scrim (alpha 0.5) unblurred, so only its card is frosted.
hl.layer_rule({ match = { namespace = "^(omarchy-bar|omarchy-notifications)$" }, blur = true, ignore_alpha = 0.2 })
hl.layer_rule({ match = { namespace = "^(omarchy-menu|omarchy-clipboard|omarchy-emojis)$" }, blur = true, ignore_alpha = 0.6 })
